    d.page(o['title'],f"{o['id']} · {o['kind']} · {o['site']} · {o['season']}")
    d.para(o['concept']);d.picture(o['image']);d.heading('Why here');d.para(o['reason']);d.para('Proposed work. Site, partners and production budget remain subject to review.',True)
    d.page('The visitor experience',o['title'])
    for i,s in enumerate(o['experience'],1):d.para(f'{i}. {s}')
    d.heading('Space and materials');d.para(o['footprint']);d.para(o['materials']);d.diagram(o)
    d.page('Works and production estimate',o['title'])
    d.para('Works are selected from the regenerated atlas. Each has a world master and a Japan companion. Study prints use smaller sheets; all masters remain available at full print size.',True)
    d.para('\n'.join(o['works']),True)
    d.table([['Planning allowance','JPY']]+[[n,f'{v:,}'] for n,v in o['budget']]+[['Total',f"{o['total']:,}"]])
    d.para('These are planning allowances, not supplier quotations. They include the stated travel/access items and contingency. No subsidy or host contribution is committed. Any tax, fee or site requirement absent from a supplier quote must fit within the total or trigger revision.',True)
    d.page('Making the work',o['title'])
    d.table([['Stage','Proposed timing'],['Confirm host, room and local questions','After selection; early 2027'],['Co-design and physical sample','Mid to late 2027'],['Confirm permissions, costs and access','At least 12 weeks before opening'],['Refresh labels and produce final prints','6–8 weeks before opening'],['Install, test and hand over care guide','Before the chosen 2028 season'],['Remove, return and archive by agreement','After the season']],[CW*.62,CW*.38])
    d.heading('Human review before production');d.para(o['review']);d.heading('Sources')
    for s in source_notes:d.para(s,True)
    d.save()

