for o in OPTIONS:
    lines+=['',f"## {o['id']} — {o['title']}",'',o['concept'],'',o['reason'],'',o['footprint'],'',o['materials'],'','Visitor sequence:','']+[f'{i}. {s}' for i,s in enumerate(o['experience'],1)]+['',f"Planning total: JPY {o['total']:,}. These are allowances, not quotations.",'','Human review: '+o['review']]
lines+=['','## Selection and next steps','','E1 is the recommended exhibition; V1 is the simplest event; I1 is the simplest independent installation. I2 needs site-specific engineering and should be selected only with a suitable host and realistic fabrication capacity. Review the nine catalogs, choose up to three plans, confirm applicant details and finish the application packet.','',*source_notes]
(OUT/'proposal/proposal-and-options.md').write_text('\n'.join(lines)+'\n')

# Source annex: exact country values and the principal definition safeguards.
summary=json.loads((ROOT/'assets.static/petroleum/normalized/summary.json').read_text())
national=list(csv.DictReader((ROOT/'assets.static/petroleum/normalized/national-series.csv').open()))
d=Doc(OUT/'proposal/petroleum-source-annex.pdf','Petroleum source annex')
d.page('Petroleum / what is integrated','OPEC WOO 2026 and independent country sources')
d.heading('Executive Summary');d.para(f"The OPEC import retains {summary['workbooks']} workbooks, {summary['worksheets']} worksheets and {summary['nonempty_cells']:,} nonempty cells. The coverage register includes {summary['opec_countries_and_territories']} countries and territories; {summary['countries_with_indexed_numeric_cells']} have directly indexed country figures. Regional definitions do not imply a separate country value.")
d.para(f"EIA adds {summary['eia_country_count']} countries and covers Russia, Brazil, Canada, Venezuela, Mexico and the USA. Brazilian ANP and Statistics Canada add independent national production and refinery-input series. UNSD supplies the existing global refinery-throughput layer, including Japan.")
d.para('All files are nested under assets.static/petroleum by source. The normalized tables retain source file, worksheet/cell or table/line, metric, unit, period and estimate/forecast status. The offline source explorer lets a reader search those records.');d.heading('Keep the measures separate');d.para('Production is not refinery throughput. Crude-only output is not all liquids. Capacity is not utilization. OPEC 2030–2050 values are projections. No regional total is assigned to each country, and missing values are never zero.')
d.page('Independent country coverage','EIA October 2026 · 2025 annual values · million barrels/day')
d.table([['Country','Petroleum + other liquids','Table']]+[[r['iso3'],str(r['eia_liquids_2025_mbpd']) if r['eia_liquids_2025_mbpd']!='' else 'not separately listed',r['eia_source_table']] for r in summary['focus']],[CW*.22,CW*.53,CW*.25])
d.para('Source: EIA STEO October 2026, tables 3b/3c. These historical/estimated annual values include crude oil, lease condensate, natural gas plant liquids, other liquids, processing gain and unaccounted liquids. The source contains separate quarterly and 2026–2027 estimate/forecast values; those remain in eia-series.csv.',True)
d.para('Russia, Venezuela and Mexico are covered by EIA independent of the OPEC workbooks. No newer machine-readable national source from those governments was ingested. Japan remains present in the UNSD refinery dataset; its blank EIA production entry is not zero.',True)
d.heading('OPEC membership is source-specific');d.para('Do not infer membership from a country’s inclusion in a report. OPEC’s DoC regional definition and EIA’s October 2026 OPEC/OPEC+ groupings differ. The import retains the original group labels and dates rather than imposing one membership list on both sources.',True)
d.page('National series and reconciliation','Original units remain available in national-series.csv')
rows=[['2025 national measure','Value / original unit']]
for r in national:
    if r['period']=='2025':rows.append([r['iso3']+' · '+r['metric'],f"{float(r['value']):,.3f} {r['unit']}"])
d.table(rows,[CW*.53,CW*.47]);d.para('ANP: sum the mutually exclusive basin or feed-origin rows; crude/condensate feed excludes the separate other-feed category. Canada: sum the 12 national monthly observations, without adding provinces or combining crude with equivalent products twice. USA: annual crude-input column in EIA table 4b.',True)
d.para('Canada’s crude plus equivalent-products totals sum to 310,930,332 m³ in 2025, consistent with Statistics Canada’s rounded 310.9 million m³ release. ANP’s crude/condensate production implies about 3.770 million barrels/day using 365 days; EIA’s 4.65 million all-liquids figure has a broader definition.',True)
d.page('Refinery sources and remaining reviews','Verified replacement for the broken upstream download')
d.para('The former UNdata DownloadHandler refinery export returns HTTP 404. The UNdata website still references that handler; a redirect or renamed handler was not confirmed. A working official alternative is the UNSD SDMX energy endpoint, commodity GR and transaction 086 (total refinery throughput).')
d.para('https://data.un.org/WS/rest/data/UNSD,DF_UNDATA_ENERGY,/A..GR.086/?startPeriod=2018&format=csv',True)
d.para('The SDMX unit is tonnes with multiplier 3: thousand metric tonnes. The output transaction is a different measure. Country labels are resolved from the official energy structure. Raw API data, the structure and the normalized extract are retained in petroleum/un-statistics.',True)
d.heading('Austria and other sources');d.para('OPEC is based in Vienna. WKO’s energy/fuel industry pages provide Austrian refinery context; its industry-report PDF download failed in this run. The Energy Institute download page was found, but automated retrieval returned HTTP 403. Neither failed download contributes numerical observations to the maps.',True)
d.heading('Before public release');d.para('Review OPEC reuse terms for report excerpts, finalize translated captions, and confirm that source periods remain visible. Check the ANP metadata inconsistencies (a stale resource-name/year field) against the archived title, unit and CSV years. Keep the raw files and do not silently rewrite source records.',True)
d.para('Primary links: https://www.eia.gov/outlooks/steo/data.php?type=tables ; https://www150.statcan.gc.ca/t1/tbl1/en/tv.action?pid=2510006301 ; https://www.gov.br/anp/pt-br/centrais-de-conteudo/dados-abertos/anuario/anuario-estatistico-2026-dados-abertos ; https://www.wko.at/industrie/energierohstoff-kraftstoff/kennzahlen-mineraloelindustrie',True);d.save()
